   164	          status = ares_expand_name(vptr, abuf, alen, &naptr_curr->replacement, &len);
   165	          if (status != ARES_SUCCESS)
   166	            break;
   167	        }
   168	
   169	      /* Don't lose memory in the next iteration */
   170	      ares_free (rr_name);
   171	      rr_name = NULL;
   172	
   173	      /* Move on to the next record */
   174	      aptr += rr_len;
   175	    }
   176	
   177	  if (hostname)
   178	    ares_free (hostname);
   179	  if (rr_name)
   180	    ares_free (rr_name);
   181	
   182	  /* clean up on error */
   183	  if (status != ARES_SUCCESS)
   184	    {
   185	      if (naptr_head)
   186	        ares_free_data (naptr_head);
   187	      return status;
   188	    }
   189	
   190	  /* everything looks fine, return the data */
   191	  *naptr_out = naptr_head;
   192	
   193	  return ARES_SUCCESS;
   194	}
